def is_power_of_5(N):
    if N <= 0:
        return False, None
    k = 0
    while N > 1 and N % 5 == 0:
        N //= 5
        k += 1
    return N == 1, k

n_values = range(3, 9)
results = []
print("Results (n, k):")
for n in n_values:
    value = (2**n) - 3
    is_power, k = is_power_of_5(value)
    if is_power:
        results.append((n, k))
        print(f"n={n}: 2^{n} - 3 = {value} = 5^{k}. Found (n, k) = ({n}, {k})")
    else:
        print(f"n={n}: 2^{n} - 3 = {value}. Not a power of 5.")

print("\nAll found results:", results)
